public class FollowUpTaskService {

    /**
     * Creates a follow-up Task for each supplied Opportunity.
     * Returns the set of Opportunity IDs for which the Task could NOT be created
     * (empty set when every task was created successfully).
     *
     * Uses a single bulk DML (Database.insert, allOrNone = false) so that:
     *   - one validation-rule failure does not prevent the others from being created, and
     *   - the call stays within the 150 DML-statement / 100 SOQL-query governor limits
     *     even at the upper end of the stated 150–250 opportunity range.
     */
    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedOpportunityIds = new Set<Id>();

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOpportunityIds;
        }

        // Single SOQL – fetch only the fields we need.
        List<Opportunity> opportunities = [
            SELECT Id, Name, OwnerId
            FROM Opportunity
            WHERE Id IN :opportunityIds
        ];

        if (opportunities.isEmpty()) {
            return failedOpportunityIds;
        }

        Date activityDate = Date.today().addDays(7);

        // Build the task list and keep a parallel list of the corresponding
        // opportunity IDs so we can map SaveResults back after the DML.
        List<Task> tasks = new List<Task>();
        List<Id> oppIdOrder = new List<Id>();

        for (Opportunity opp : opportunities) {
            tasks.add(new Task(
                WhatId       = opp.Id,
                OwnerId      = opp.OwnerId,
                Subject      = 'Follow up: ' + opp.Name,
                ActivityDate = activityDate,
                Status       = 'Not Started',
                Priority     = 'Normal'
            ));
            oppIdOrder.add(opp.Id);
        }

        // Single DML with allOrNone = false:
        //   - records that pass validation are inserted;
        //   - records that fail (e.g. compliance validation rule) are flagged
        //     in the SaveResult without rolling back the successful ones.
        Database.SaveResult[] results = Database.insert(tasks, false);

        for (Integer i = 0; i < results.size(); i++) {
            if (!results[i].isSuccess()) {
                failedOpportunityIds.add(oppIdOrder[i]);
            }
        }

        return failedOpportunityIds;
    }
}
