    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Query the opportunities we need
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>(
            [SELECT Id, Name, CloseDate, OwnerId FROM Opportunity WHERE Id IN :opportunityIds]
        );

        Integer sentCount = 0;

        for (Id oppId : opportunityIds) {
            Opportunity opp = oppMap.get(oppId);
            if (opp == null || opp.OwnerId == null) {
                continue;
            }

            try {
                Messaging.SingleEmailMessage mail = new Messaging.SingleEmailMessage();
                mail.setTargetObjectId(opp.OwnerId);
                mail.setSaveAsActivity(false);
                mail.setSubject('Renewal due: ' + opp.Name);
                mail.setPlainTextBody(
                    'Hi,\n\nYour opportunity "' + opp.Name + '" is due for renewal on ' + 
                    (opp.CloseDate != null ? opp.CloseDate.format() : 'an unknown date') + '.\n\nPlease review it soon.\n\nRegards'
                );

                Messaging.SendEmailResult[] results = Messaging.sendEmail(new Messaging.SingleEmailMessage[] { mail });

                if (results != null && results.size() == 1 && results[0].isSuccess()) {
                    sentCount++;
                }
            } catch (Exception e) {
                // Log or handle; continue to next opportunity
                continue;
            }
        }

        return sentCount;
    }
}
