public class AccountCountrySync {

    /**
     * Syncs Contact.MailingCountry to Account.BillingCountry when the account
     * country changes.  Only contacts whose MailingCountry is null or still
     * equals the account's *previous* country are updated; contacts that have
     * been set to a different country (e.g. working abroad) are left alone.
     *
     * Bulk-safe: one SOQL query + one DML statement regardless of batch size.
     */
    public static void handle(Map<Id, Account> oldMap, List<Account> newAccounts) {

        // ── 1. Identify accounts whose BillingCountry actually changed ──────
        Map<Id, String> oldCountryById = new Map<Id, String>();
        Map<Id, String> newCountryById = new Map<Id, String>();

        for (Account acc : newAccounts) {
            Account oldAcc = oldMap.get(acc.Id);
            if (oldAcc == null) {
                continue; // shouldn't happen in after update, but be safe
            }
            String oldCountry = oldAcc.BillingCountry;
            String newCountry = acc.BillingCountry;
            if (oldCountry != newCountry) {
                oldCountryById.put(acc.Id, oldCountry);
                newCountryById.put(acc.Id, newCountry);
            }
        }

        // Nothing changed → exit early, no query, no DML
        if (oldCountryById.isEmpty()) {
            return;
        }

        // ── 2. One query: contacts belonging only to the changed accounts ───
        List<Contact> contacts = [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :oldCountryById.keySet()
        ];

        // ── 3. Group contacts by AccountId for O(1) lookup ──────────────────
        Map<Id, List<Contact>> contactsByAccount = new Map<Id, List<Contact>>();
        for (Contact c : contacts) {
            if (!contactsByAccount.containsKey(c.AccountId)) {
                contactsByAccount.put(c.AccountId, new List<Contact>());
            }
            contactsByAccount.get(c.AccountId).add(c);
        }

        // ── 4. Pick the contacts that need updating ──────────────────────────
        List<Contact> toUpdate = new List<Contact>();

        for (Id accId : oldCountryById.keySet()) {
            String oldCountry = oldCountryById.get(accId);
            String newCountry = newCountryById.get(accId);

            List<Contact> accContacts = contactsByAccount.get(accId);
            if (accContacts == null) {
                continue;
            }

            for (Contact c : accContacts) {
                // Update if MailingCountry is blank OR still equals the old
                // account country.  (null == null is true in Apex, which
                // correctly handles the "old country was blank" case.)
                if (c.MailingCountry == null || c.MailingCountry == oldCountry) {
                    c.MailingCountry = newCountry;
                    toUpdate.add(c);
                }
            }
        }

        // ── 5. One DML statement ─────────────────────────────────────────────
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
