import { LightningElement, api } from 'lwc';

export default class OrderLinesPanel extends LightningElement {
    @api lines = [];
    showError = false;

    handleClick(event) {
        const action = event.currentTarget.dataset.action;
        if (action === 'reset') {
            this.resetAll();
        } else if (action === 'submit') {
            this.submitAll();
        }
    }

    getEditors() {
        return this.template.querySelectorAll('c-line-item-editor');
    }

    resetAll() {
        this.getEditors().forEach((editor) => editor.reset());
    }

    submitAll() {
        const editors = this.getEditors();
        let allValid = true;

        editors.forEach((editor) => {
            const isValid = editor.validate();
            if (!isValid) {
                allValid = false;
            }
        });

        if (allValid) {
            this.showError = false;
            const lines = editors.map((editor) => editor.getValue());
            this.dispatchEvent(
                new CustomEvent('submit', { detail: { lines } })
            );
        } else {
            this.showError = true;
        }
    }
}
