public class EmployerService {

    /**
     * Sets the current employer (Organization Account) for each Contact in the map.
     * 
     * Uses NPSP's standard affiliation mechanism:
     *  - Creates a new Current, primary NPE01__Affiliation__c for each contact/org pair.
     *  - Updates the Contact's NPE01__Primary_Affiliation__c lookup to the new affiliation.
     *  - NPSP's own trigger/flow automatically transitions the previous primary
     *    affiliation to Former with an end date of today.
     * 
     * @param employerByContactId  Keys = Contact Ids, Values = Organization Account Ids.
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = employerByContactId.keySet();

        // ── SOQL Query 1 (of max 2) ────────────────────────────────────────────
        // Retrieve each contact along with its current primary affiliation and
        // the organization that affiliation points to, so we can detect no-ops.
        Map<Id, Contact> contactMap = new Map<Id, Contact>(
            [
                SELECT Id,
                       NPE01__Primary_Affiliation__c,
                       NPE01__Primary_Affiliation__r.NPE01__Organization__c
                FROM Contact
                WHERE Id IN :contactIds
            ]
        );

        List<NPE01__Affiliation__c> newAffiliations = new List<NPE01__Affiliation__c>();
        Map<Id, Integer> contactToIndex = new Map<Id, Integer>();

        for (Id contactId : contactIds) {
            Id orgId = employerByContactId.get(contactId);
            Contact contact = contactMap.get(contactId);

            // Skip contacts that don't exist in the org
            if (contact == null) {
                continue;
            }

            // No-op: the target organization is already the contact's primary affiliation
            if (contact.NPE01__Primary_Affiliation__c != null
                && contact.NPE01__Primary_Affiliation__r != null
                && contact.NPE01__Primary_Affiliation__r.NPE01__Organization__c == orgId) {
                continue;
            }

            NPE01__Affiliation__c aff = new NPE01__Affiliation__c(
                NPE01__Contact__c        = contactId,
                NPE01__Organization__c   = orgId,
                NPE01__Primary__c        = 'Employee',
                NPE01__Status__c         = 'Current',
                NPE01__StartDate__c      = Date.today()
            );

            contactToIndex.put(contactId, newAffiliations.size());
            newAffiliations.add(aff);
        }

        if (newAffiliations.isEmpty()) {
            return;
        }

        // ── DML 1 (of max 2): Insert the new affiliations ─────────────────────
        insert newAffiliations;

        // ── DML 2 (of max 2): Point each contact's primary-affiliation lookup
        //    to its new affiliation. NPSP's standard mechanism (trigger/flow on
        //    Contact / Affiliation) then:
        //      • marks the previous primary affiliation Former + EndDate = today
        //      • confirms the new affiliation as Current
        //    The contact's Household Account is untouched.
        List<Contact> contactsToUpdate = new List<Contact>();
        for (Id contactId : contactToIndex.keySet()) {
            contactsToUpdate.add(new Contact(
                Id                              = contactId,
                NPE01__Primary_Affiliation__c   = newAffiliations.get(contactToIndex.get(contactId)).Id
            ));
        }

        update contactsToUpdate;
    }
}
