public class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;
        public Id opportunityId;
        public String errorMessage;
    }

    /**
     * Imports a list of one-off gifts through NPSP's Data Import engine (BDI).
     * Each gift is staged as an NPE01__npsp_data_import__c row, the batch is
     * processed synchronously via NPE01__ImportController, and one ImportResult
     * is returned per input gift in the same order.
     *
     * @param gifts List of web-collected gifts to import.
     * @return One ImportResult per gift, in input order.
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        if (gifts == null || gifts.isEmpty()) {
            return new List<ImportResult>();
        }

        // ── 1. Create the Data Import batch ──────────────────────────────────
        NPE01__npsp_data_import_batch__c batch = new NPE01__npsp_data_import_batch__c();
        batch.NPE01__Status__c = 'Pending';
        // Contact matching: first name + last name + email (org default)
        batch.NPE01__Contact_Match_1__c = 'NPE01__First_Name__c';
        batch.NPE01__Contact_Match_2__c = 'NPE01__Last_Name__c';
        batch.NPE01__Contact_Match_3__c = 'NPE01__Email__c';
        // Opportunity matching: intentionally left unset → never match existing donations
        batch.NPE01__Create_Recs__c = true;
        batch.NPE01__Update_Recs__c = true;
        batch.NPE01__Merge_Recs__c = false;

        insert batch;

        // ── 2. Stage one import row per gift ─────────────────────────────────
        List<NPE01__npsp_data_import__c> importRows = new List<NPE01__npsp_data_import__c>();
        for (Integer i = 0; i < gifts.size(); i++) {
            WebGift gift = gifts[i];
            NPE01__npsp_data_import__c row = new NPE01__npsp_data_import__c();
            row.NPE01__Batch__c    = batch.Id;
            row.NPE01__RowNum__c   = i + 1;
            row.NPE01__First_Name__c       = gift.firstName;
            row.NPE01__Last_Name__c        = gift.lastName;
            row.NPE01__Email__c            = gift.email;
            row.NPE01__Opportunity_Name__c = 'Donation ' + gift.giftDate;
            row.NPE01__Close_Date__c       = gift.giftDate;
            row.NPE01__Amount__c           = gift.amount;
            importRows.add(row);
        }
        insert importRows;

        // ── 3. Process synchronously via NPSP's Apex Data Import API ─────────
        // NPE01__ImportController handles per-row error isolation: a failed
        // row is marked with status 'Error' and its ErrorMessage populated,
        // while remaining rows continue to be processed.
        NPE01__ImportController.processBatch(batch.Id);

        // ── 4. Read back processed rows keyed by row number ──────────────────
        Map<Integer, NPE01__npsp_data_import__c> processedMap = new Map<Integer, NPE01__npsp_data_import__c>();
        for (NPE01__npsp_data_import__c row : [
                SELECT NPE01__RowNum__c,
                       NPE01__Status__c,
                       NPE01__ErrorMessage__c,
                       NPE01__Contact__c,
                       NPE01__Opportunity__c
                FROM NPE01__npsp_data_import__c
                WHERE NPE01__Batch__c = :batch.Id
        ]) {
            processedMap.put(row.NPE01__RowNum__c, row);
        }

        // ── 5. Build results in input order ──────────────────────────────────
        List<ImportResult> results = new List<ImportResult>();
        for (Integer i = 0; i < importRows.size(); i++) {
            ImportResult result = new ImportResult();
            NPE01__npsp_data_import__c row = processedMap.get(i + 1);

            if (row != null) {
                result.success     = (row.NPE01__Status__c == 'Imported');
                result.contactId   = row.NPE01__Contact__c;
                result.opportunityId = row.NPE01__Opportunity__c;
                if (!result.success) {
                    result.errorMessage = row.NPE01__ErrorMessage__c;
                }
            } else {
                result.success = false;
                result.errorMessage = 'Import row not found after processing';
            }
            results.add(result);
        }

        return results;
    }
}
```

