```apex
public class GiftService {

    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        // --- Validate amount ---
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be a positive, non-zero value.');
        }

        // --- Validate contact exists ---
        List<Contact> contacts = [
            SELECT Id, FirstName, LastName, Npe01__AccountId
            FROM Contact
            WHERE Id = :contactId
        ];
        if (contacts.isEmpty()) {
            throw new IllegalArgumentException('Contact not found: ' + contactId);
        }

        Contact contact = contacts[0];
        Id householdAccountId = contact.Npe01__AccountId;

        // --- Gather all household members ---
        List<Contact> householdMembers = [
            SELECT Id
            FROM Contact
            WHERE Npe01__AccountId = :householdAccountId
        ];

        // --- Build opportunity name: "FirstName LastName Donation yyyy-MM-dd" ---
        String oppName = contact.FirstName + ' ' + contact.LastName
                       + ' Donation ' + giftDate.format('yyyy-MM-dd');

        // --- Create the Opportunity (Closed Won donation) ---
        Opportunity opp = new Opportunity(
            Name = oppName,
            StageName = 'Closed Won',
            CloseDate = giftDate,
            Type = 'Donation',
            Amount = amount,
            Npe01__RelatedAccountId = householdAccountId,
            Npe01__PrimaryContactId = contactId
        );
        insert opp;

        // --- Create Contact Roles ---
        // The donor gets 'Donor'; every other household member gets 'Household Member'.
        // Each contact appears exactly once, so no duplicate roles.
        List<ContactRole> contactRoles = new List<ContactRole>();
        for (Contact member : householdMembers) {
            contactRoles.add(new ContactRole(
                ContactId = member.Id,
                OpportunityId = opp.Id,
                Rolename = 'Other',
                Npe01__ContactRole = (member.Id == contactId) ? 'Donor' : 'Household Member'
            ));
        }
        insert contactRoles;

        // --- Create exactly one NPSP Payment ---
        Npe01__Payment__c payment = new Npe01__Payment__c(
            Npe01__OppPayment__c = opp.Id,
            Npe01__Account__c = householdAccountId,
            Npe01__Amount__c = amount,
            Npe01__Status__c = 'Paid',
            Npe01__Payment_Date__c = giftDate
        );
        insert payment;

        return opp.Id;
    }
}
