public class OPP_MajorGiftFollowUp_TDTM extends TriggerHandler {

    public OPP_MajorGiftFollowUp_TDTM() {
    }

    public override void onInsert() {
        List<Task> tasks = new List<Task>();

        for (Opportunity opp : Trigger.new) {
            if (isMajorGift(opp)) {
                tasks.add(buildTask(opp));
            }
        }

        if (!tasks.isEmpty()) {
            Database.insert(tasks);
        }
    }

    public override void onUpdate() {
        List<Task> tasks = new List<Task>();

        for (Integer i = 0; i < Trigger.new.size(); i++) {
            Opportunity newOpp = Trigger.new[i];
            Opportunity oldOpp = Trigger.old[i];

            if (isMajorGift(newOpp) && !isMajorGift(oldOpp)) {
                tasks.add(buildTask(newOpp));
            }
        }

        if (!tasks.isEmpty()) {
            Database.insert(tasks);
        }
    }

    private static Boolean isMajorGift(Opportunity opp) {
        return opp.StageName == 'Closed Won'
            && opp.Amount != null
            && opp.Amount >= 5000;
    }

    private static Task buildTask(Opportunity opp) {
        Task t = new Task(
            Subject      = 'Major gift thank-you call',
            Priority     = 'High',
            Status       = 'Not Started',
            WhatId       = opp.Id,
            WhoId        = opp.npsp__Primary_Contact__c,
            OwnerId      = opp.OwnerId,
            ActivityDate = opp.CloseDate != null ? opp.CloseDate.addDays(3) : null
        );
        return t;
    }
}
